wrapper='''package org.wangshu.scan.test;public final class EncoderEndpoint{private final ImeEditorProbe probe;public EncoderEndpoint(String session,String instance){probe=new ImeEditorProbe(session,instance);}public void textChanged(){probe.changed(true);}public void stateChanged(){probe.changed(false);}public void selectionChanged(int s,int e){probe.selectionChanged(s,e);}public String wire(int len,int s,int e,boolean a,boolean shown,boolean f,boolean w,boolean alive){return probe.snapshot(len,s,e,a,shown,f,w,alive);}public void forceCounterMax()throws Exception{java.lang.reflect.Field field=ImeEditorProbe.class.getDeclaredField("revision");field.setAccessible(true);field.setLong(probe,Long.MAX_VALUE);}}'''
